 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { scan, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    usageError()
    return
  }

  const input = fs.readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(input)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  let output
  if (mode === 'tokens') {
    output = tokens
      .map((t) => {
        const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.value) : t.text
        return `${t.line}:${t.col} ${t.kind} ${body}\n`
      })
      .join('')
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    output = STAT_KINDS.map((k) => `${k} ${counts[k]}\n`).join('') + `total ${tokens.length}\n`
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
